import{PINS}from'./pins.mjs';import{prepareLosslessWater}from'./water-cache.mjs';import{createSparseEnvironment}from'./sparse-environment.mjs';import{createClockConsumer}from'./clock-consumer.mjs';
const sourceSHA='8b4fa4c1de830dada770e2ef10a66db93911ee0844f1daf51e17492c9cf7bdd2',sha=async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),v=>v.toString(16).padStart(2,'0')).join('');
async function defaultDecode(b){let image=null,c=null,result,error;try{image=await createImageBitmap(new Blob([b]));if(image.width!==2836||image.height!==1820)throw Error('WETLAND_SOURCE_SIZE');c=new OffscreenCanvas(2836,1820);const g=c.getContext('2d');g.drawImage(image,0,0);result=g.getImageData(0,0,2836,1820).data}catch(e){error=e}finally{try{image?.close()}catch(e){error??=e}try{if(c)c.width=c.height=1}catch(e){error??=e}image=null;c=null}if(error)throw error;return result}
const defaultInflate=async b=>new Uint8Array(await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('deflate'))).arrayBuffer());
/** Lightweight exact data closure. Host owns clock/RAF; explicit skipped updates on phase miss. */
export async function loadWetlandEnvironment({fetcher=fetch,decodeRGBA=defaultDecode,inflate=defaultInflate,signal,initialMs=0,getElapsedMs=null}={}){
 let closed=false,cache=null,consumer=null,inputs=null;const check=()=>{if(closed||signal?.aborted)throw Error('WETLAND_ENV_CLOSED')};const read=async path=>{check();const pin=PINS[path];if(!Object.hasOwn(PINS,path))throw Error('WETLAND_ENV_PATH');const r=await fetcher(new URL(path,import.meta.url),{signal});if(!r.ok)throw Error('WETLAND_ENV_MISSING');const b=new Uint8Array(await r.arrayBuffer());check();if(b.length!==pin.bytes||await sha(b)!==pin.sha256)throw Error('WETLAND_ENV_PIN');check();return b};const cast=async(path,T)=>{const b=await read(path);return new T(b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength))};const json=async path=>JSON.parse(new TextDecoder().decode(await read(path)));const dispose=()=>{if(closed)return;closed=true;let error;for(const own of[consumer,cache])try{own?.dispose()}catch(e){error??=e}consumer=null;cache=null;inputs=null;if(error)throw error};
 try{if(!Number.isFinite(initialMs))throw Error('WETLAND_ENV_CLOCK');const layout=await json('WATER_LOSSLESS_LAYOUT.json');cache=await prepareLosslessWater({layout,read,inflate,signal});const rgba=await decodeRGBA(await read('../assets/wetland-selected-env.png'));check();if(!(rgba instanceof Uint8ClampedArray)||rgba.length!==2836*1820*4)throw Error('WETLAND_ENV_RGBA');inputs={source:rgba,waterCache:cache,waterManifest:{sourceSHA},lightManifest:await json('LIGHT_MANIFEST.json'),lightIndices:await cast('light_indices.u32',Uint32Array),transmission:await cast('light_transmission.f64',Float64Array),reedIndices:await cast('reed_ids.u32',Uint32Array),reedFlags:await cast('reed_donor_flags.u8',Uint8Array),reedClearance:await cast('reed_clearance_sparse.f32',Float32Array)};check();consumer=createClockConsumer({waterCache:cache,render:createSparseEnvironment(inputs)});inputs=null;const primeMs=getElapsedMs?getElapsedMs():initialMs;if(!Number.isFinite(primeMs))throw Error('WETLAND_ENV_CLOCK');await consumer.prime(primeMs);check();return Object.freeze({sourceSHA,frame(options){check();return consumer.frame(options)},stats(){check();return{...consumer.stats(),water:cache.memory()}},async settled(){check();await consumer.settled();check()},dispose})}catch(e){try{dispose()}catch{}throw e}
}
